int top = 0, bottom = rows - 1;
int left = 0, right = cols - 1;

while (top <= bottom && left <= right) {

    for (int c = left; c <= right; c++) process(grid[top][c]);
    top++;

    for (int r = top; r <= bottom; r++) process(grid[r][right]);
    right--;

    if (top <= bottom) {
        for (int c = right; c >= left; c--) process(grid[bottom][c]);
        bottom--;
    }

    if (left <= right) {
        for (int r = bottom; r >= top; r--) process(grid[r][left]);
        left++;
    }
}

